import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const a="/assets/assistent-einheit.Cmfelz8C.png",g=JSON.parse('{"title":"Quellen, Einheiten und Vorzeichen","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/01.quellen-und-einheiten.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","filePath":"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","lastUpdated":null}'),s={name:"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md"};function d(u,e,h,l,o,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="quellen-einheiten-und-vorzeichen" tabindex="-1">Quellen, Einheiten und Vorzeichen <a class="header-anchor" href="#quellen-einheiten-und-vorzeichen" aria-label="Permalink to &quot;Quellen, Einheiten und Vorzeichen&quot;">​</a></h1><p><a id="separate-import-feed-one-datapoint"></a></p><h2 id="wie-trenne-ich-bezug-und-einspeisung-ein-datenpunkt-mit-vorzeichen" tabindex="-1">Wie trenne ich Bezug und Einspeisung (ein Datenpunkt mit Vorzeichen)? <a class="header-anchor" href="#wie-trenne-ich-bezug-und-einspeisung-ein-datenpunkt-mit-vorzeichen" aria-label="Permalink to &quot;Wie trenne ich Bezug und Einspeisung (ein Datenpunkt mit Vorzeichen)?&quot;">​</a></h2><p>Mit zwei Quellen, denn SourceAnalytix wertet das Vorzeichen nicht aus. Die erste nimmt den Datenpunkt für den Bezug, die zweite einen Alias mit umgedrehtem Vorzeichen für die Einspeisung. Beide bekommen „Negative Werte ignorieren“.</p><ol><li>Lege im Tab „Preisdefinitionen“ zwei Preise in <code>kWh</code> an: <code>Strom Bezug</code> mit Kostenart „Kosten“ und <code>Einspeisung</code> mit Kostenart „Erträge“. Bei der Einspeisung ist der „Preis pro Einheit“ deine Vergütung je kWh.</li><li>Lege im Reiter „Objekte“ einen Alias auf den Leistungs-Datenpunkt an, der das Vorzeichen umdreht (<code>-val</code>), mit der Einheit <code>W</code>.</li><li>Lege mit „Quelle hinzufügen“ eine Quelle für den Original-Datenpunkt mit Messart „Leistung“ und Preis <code>Strom Bezug</code> an.</li><li>Lege genauso eine Quelle für den Alias mit dem Preis <code>Einspeisung</code> an.</li><li>Setze bei beiden in der Detailansicht unter „Einstellungen“ „Negative Werte ignorieren“ und klicke auf „⚡ Übernehmen“.</li></ol><p>Der Bezug steht danach unter <code>currentYear.consumed</code>, die Einspeisung unter <code>currentYear.delivered</code> und die Erlöse unter <code>currentYear.earnings</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ohne „Negative Werte ignorieren“ zieht die Einspeisung den Gesamtstand des Bezugs herunter. Der Tagesverbrauch zeigt dann nur den Saldo und kann negativ werden.</p></div><p>Hat dein Stromzähler eigene Zählerstände für Bezug und Einspeisung, nimm lieber diese als zwei Zählerstand-Quellen. Das ist genauer.</p><p><strong>Siehe auch:</strong> <a href="#track-pv-yield-feed-earnings">PV-Ertrag, Einspeisung und Erlöse</a> · <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">Wie ordne ich Preise zu?</a></p><p><a id="unit-datapoint-kwh-wh-m3"></a></p><h2 id="welche-einheit-stelle-ich-am-datenpunkt-ein-kwh-statt-wh-m3-statt-liter" tabindex="-1">Welche Einheit stelle ich am Datenpunkt ein (kWh statt Wh, m³ statt Liter)? <a class="header-anchor" href="#welche-einheit-stelle-ich-am-datenpunkt-ein-kwh-statt-wh-m3-statt-liter" aria-label="Permalink to &quot;Welche Einheit stelle ich am Datenpunkt ein (kWh statt Wh, m³ statt Liter)?&quot;">​</a></h2><p>Die Einheit, in der der Datenpunkt wirklich liefert. Meist erkennt der Assistent sie selbst („Erkannt aus dem Datenpunkt: …“). In welcher Einheit du die Werte siehst, bestimmt die Preisdefinition. Von Wh nach kWh oder von l nach m³ rechnet SourceAnalytix selbst um.</p><p><img src="'+a+'" alt="Assistent, Schritt „Einheit“ mit „Erkannt aus dem Datenpunkt“"></p><p>Typische Fehler:</p><ul><li><strong>Zählerstand als <code>W</code> beschriftet:</strong> Der Wert wird über die Zeit aufsummiert und wird absurd hoch. Wähle <code>Wh</code> oder <code>kWh</code>.</li><li><strong>Leistung als <code>kWh</code> beschriftet:</strong> Jeder Wert gilt als Zählerstand. Wähle <code>W</code> oder <code>kW</code>.</li><li><strong><code>Wh</code> und <code>kWh</code> verwechselt:</strong> Alles ist um den Faktor 1.000 falsch.</li></ul><p>Erkennt SourceAnalytix keine Einheit, meldet der Tab „Probleme“ „Einheit fehlt oder wird nicht erkannt“. Mit „Beheben“ wählst du sie aus.</p><h3 id="warum-kwh-statt-m3-erscheint" tabindex="-1">Warum kWh statt m³ erscheint <a class="header-anchor" href="#warum-kwh-statt-m3-erscheint" aria-label="Permalink to &quot;Warum kWh statt m³ erscheint&quot;">​</a></h3><p>Die gewählte Preisdefinition rechnet in <code>kWh</code>. Lege für Gas einen eigenen Preis in <code>m³</code> an und wähle ihn bei der Quelle. Kubikmeter Gas rechnet SourceAnalytix nicht in kWh um; passen die Einheiten nicht zusammen, kannst du den Preis gar nicht wählen.</p><h3 id="wenn-du-die-einheit-nachtraglich-anderst" tabindex="-1">Wenn du die Einheit nachträglich änderst <a class="header-anchor" href="#wenn-du-die-einheit-nachtraglich-anderst" aria-label="Permalink to &quot;Wenn du die Einheit nachträglich änderst&quot;">​</a></h3><p>Gespeicherte Werte rechnet SourceAnalytix nicht um. Wechselst du zu einem Preis in einer anderen Einheit als die gespeicherten Daten, etwa von kWh zu MWh, startet die Quelle nicht. Der Tab „Probleme“ zeigt dann „Preisdefinition hat eine andere Einheit als die gespeicherten Daten“. Wähle einen Preis in der alten Einheit oder lösche die Daten der Quelle und beginne neu.</p><p>War die Einheit am Datenpunkt falsch, etwa Wh statt kWh, gilt die neue ab dem nächsten Wert. Gesamtstand und Perioden korrigierst du danach mit „Zählerstand angleichen“, siehe <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte und ihre Einheit</a></p><p><a id="sourceanalytix-compute-consumption-meter-reading"></a></p><h2 id="kann-sourceanalytix-aus-leistung-w-verbrauch-und-zahlerstand-berechnen" tabindex="-1">Kann SourceAnalytix aus Leistung (W) Verbrauch und Zählerstand berechnen? <a class="header-anchor" href="#kann-sourceanalytix-aus-leistung-w-verbrauch-und-zahlerstand-berechnen" aria-label="Permalink to &quot;Kann SourceAnalytix aus Leistung (W) Verbrauch und Zählerstand berechnen?&quot;">​</a></h2><p>Ja. SourceAnalytix multipliziert jeden Leistungswert mit der Zeit bis zum nächsten und addiert das zu einem eigenen Gesamtstand. Daraus entstehen Verbrauch und Kosten in der Energie-Einheit der Preisdefinition, zum Beispiel kWh.</p><p>Der Gesamtstand beginnt bei der Aktivierung bei 0, er ist also nicht der Stand deines Stromzählers. Wie genau er ist, hängt davon ab, wie oft das Gerät sendet. Startwerte und Reset-Erkennung brauchst du nicht.</p><p>Wähle im Assistenten die Messart „Leistung“ und einen Preis in <code>Wh</code>, <code>kWh</code> oder <code>MWh</code>. Die Optionen für Leistung stehen unter <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Wenn du nur einen Leistungswert hast</a>. Mit „Zählerstand angleichen“ kannst du den Gesamtstand an einen echten Zähler anlehnen; danach laufen beide wieder auseinander.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a> · <a href="./../referenz/einstellungen#source-types-exist-meter-power">Welche Quelltypen gibt es?</a></p><p><a id="track-pv-yield-feed-earnings"></a></p><h2 id="wie-erfasse-ich-pv-ertrag-einspeisung-und-erlose" tabindex="-1">Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse? <a class="header-anchor" href="#wie-erfasse-ich-pv-ertrag-einspeisung-und-erlose" aria-label="Permalink to &quot;Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse?&quot;">​</a></h2><p>Jeder Zähler wird eine eigene Quelle mit einem Preis der Kostenart „Erträge“. Dann schreibt SourceAnalytix Lieferung und Erlöse statt Verbrauch und Kosten.</p><table tabindex="0"><thead><tr><th>Was</th><th>Datenpunkt</th><th>Preisdefinition</th></tr></thead><tbody><tr><td>PV-Ertrag</td><td>Gesamtertrag des Wechselrichters in kWh</td><td>„Erträge“; ohne Geld lässt du „Kosten“ aus</td></tr><tr><td>Einspeisung und Erlöse</td><td>Einspeisezähler des Stromzählers</td><td>„Erträge“, Preis = Einspeisevergütung</td></tr><tr><td>Netzbezug</td><td>Bezugszähler des Stromzählers</td><td>„Kosten“</td></tr></tbody></table><p>Nimm den Gesamtertrag, nicht „Ertrag heute“, der jede Nacht auf 0 springt. Die Werte stehen unter <code>currentYear.delivered</code> und <code>currentYear.earnings</code>, in der Detailansicht als „Einspeisung“ und „Erlös“. Eigenverbrauch und Autarkie berechnet SourceAnalytix nicht.</p><p><strong>Siehe auch:</strong> <a href="#separate-import-feed-one-datapoint">Bezug und Einspeisung aus einem Datenpunkt</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte</a></p><p><a id="derive-counter-flow-run-time"></a></p><h2 id="wie-leite-ich-einen-zahler-aus-durchfluss-laufzeit-oder-mehreren-geraten-ab" tabindex="-1">Wie leite ich einen Zähler aus Durchfluss, Laufzeit oder mehreren Geräten ab? <a class="header-anchor" href="#wie-leite-ich-einen-zahler-aus-durchfluss-laufzeit-oder-mehreren-geraten-ab" aria-label="Permalink to &quot;Wie leite ich einen Zähler aus Durchfluss, Laufzeit oder mehreren Geräten ab?&quot;">​</a></h2><p>Mit einem Skript. SourceAnalytix wertet jeden Datenpunkt einzeln aus und summiert über die Zeit nur Leistung und Impulse pro Minute. Für alles andere schreibt ein Skript einen steigenden Zählerstand in einer unterstützten Einheit, und du aktivierst diesen Datenpunkt.</p><table tabindex="0"><thead><tr><th>Fall</th><th>Was du tust</th></tr></thead><tbody><tr><td>Mehrere Phasen</td><td>Gesamtzähler des Geräts nehmen, sonst die Phasen per Skript summieren</td></tr><tr><td>Mehrere Geräte</td><td>je Gerät eine Quelle; eine Summe bildet ein Skript</td></tr><tr><td>Durchfluss (<code>m³/h</code>, <code>l/min</code>)</td><td>Skript addiert Rate × Zeit zu <code>m³</code> oder <code>l</code></td></tr><tr><td>Brennerlaufzeit</td><td>Skript rechnet Laufzeit × Verbrauch pro Stunde in <code>l</code> oder <code>kWh</code></td></tr><tr><td>Brennerstarts</td><td>direkt als Zählerstand mit Einheit <code>piece</code></td></tr><tr><td>Füllstand (Öltank)</td><td>Skript summiert nur die Abnahmen, ohne Nachtanken</td></tr></tbody></table><p>Am saubersten ist eine Summe, die nie fällt: Das Skript addiert je Teilzähler nur den Zuwachs und ignoriert Rückgänge. Fällt die Summe doch, behandelt die Reset-Erkennung das wie bei jedem Zähler.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="#use-script-datapoints-unreliable-sources">Skript-Datenpunkte</a></p><p><a id="use-script-datapoints-unreliable-sources"></a></p><h2 id="kann-ich-skript-datenpunkte-oder-unzuverlassige-quellen-verwenden" tabindex="-1">Kann ich Skript-Datenpunkte oder unzuverlässige Quellen verwenden? <a class="header-anchor" href="#kann-ich-skript-datenpunkte-oder-unzuverlassige-quellen-verwenden" aria-label="Permalink to &quot;Kann ich Skript-Datenpunkte oder unzuverlässige Quellen verwenden?&quot;">​</a></h2><p>Ja. Jeder Datenpunkt kann Quelle sein, ob Adapter, Skript, Alias oder Simple-API ihn schreibt. Er muss eine Zahl in einer unterstützten Einheit liefern; Text wie <code>&quot;12,5&quot;</code> geht auch.</p><ul><li>Gib dem Datenpunkt den Typ Zahl und eine Einheit, zum Beispiel <code>kWh</code>. Dann zeigt ihn der Assistent unter „Passende Datenpunkte“.</li><li>Schreibe einen Zählerstand, der nur steigt.</li><li>Ist ein Wert keine Zahl, meldet der Tab „Probleme“ „Datenpunkt liefert Text statt einer Zahl“.</li></ul><p>Ausreißer filtert nur die Reset-Erkennung: Kleine Rückgänge bis zur „Schwelle“ und eine kurze 0 werden ignoriert. Ein Sprung nach oben zählt sofort als Verbrauch. Liefert deine Quelle manchmal unsinnig hohe Werte, filtere sie vorher per Skript.</p><p>Wie viele Nachkommastellen SourceAnalytix ausgibt, stellst du bei der Quelle unter „Für Experten“ ein.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a> · <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a></p>',47)])])}const m=n(s,[["render",d]]);export{g as __pageData,m as default};
